#include "play_plan.h"
#include <stddef.h>

void pp_new_request(pp_ctx_t *c)
{
    if (c == NULL)
    {
        return;
    }
    c->retry_done = false;
    c->no_slot_retried = false;
}

/* Branch 1's refusals: why the recording's facts could not be had. */
static pp_action_t source_failure(const pp_facts_t *f)
{
    if (f->src_result == STORAGE_NOT_FOUND)
    {
        return PP_FAIL_NOT_FOUND;                    /* the list changed: no fault screen */
    }
    if (f->src_result == STORAGE_CORRUPT)
    {
        return PP_FAIL_HEADER;
    }
    return f->slot_present ? PP_FAIL_READ : PP_FAIL_REMOVED;
}

pp_action_t pp_decide(const pp_facts_t *f)
{
    if (f == NULL)
    {
        return PP_FAIL_READ;
    }
    const bool wants_effect = (f->effect != FXS_EFFECT_NONE);

    /* 0. That very file is being made: wait for it, keeping its progress. */
    if (wants_effect && f->job_same_pair)
    {
        return PP_ADOPT;
    }
    /* 1. The recording's facts, and whether Jack can play it at all. */
    if (!f->have_src)
    {
        return PP_NEED_SOURCE;
    }
    if (f->src_result != STORAGE_OK)
    {
        return source_failure(f);
    }
    if (!f->playable)
    {
        return PP_FAIL_FORMAT;
    }
    /* 2. No effect, or one this file cannot have. */
    if (!wants_effect || !f->renderable)
    {
        return PP_PLAY_ORIGINAL;
    }
    /* 3. A valid effect file plays at once: no render task is needed. */
    if (!f->have_check)
    {
        return PP_NEED_CHECK;
    }
    if (f->check == FXJ_VALID)
    {
        return PP_PLAY_FX;
    }
    /* 4. A disk error while checking it. */
    if (f->check == FXJ_IO_ERROR)
    {
        return f->slot_present ? PP_FAIL_READ : PP_FAIL_REMOVED;
    }
    /* 5. Not valid although it was just made: never prepare twice in a row. */
    if (f->retry_done)
    {
        return PP_PLAY_ORIGINAL_NOT_VALID;
    }
    /* 6. Make it first, if there is a working engine to make it. */
    return f->engine_ok ? PP_PREPARE : PP_PLAY_ORIGINAL;
}

bool pp_no_fx(const pp_facts_t *f)
{
    return (f != NULL) && (f->effect != FXS_EFFECT_NONE) && (pp_decide(f) == PP_PLAY_ORIGINAL);
}

pp_end_t pp_on_waited_end(fxj_step_t step, fxj_fail_t fail, bool no_slot_retried, bool slot_present)
{
    if (step == FXJ_WANT_DONE)
    {
        return PP_END_PLAY;
    }
    if (step != FXJ_WANT_FAILED)
    {
        return PP_END_ORIGINAL_AT_POS;               /* gave up: FxRenderTask is stalled */
    }
    switch (fail)
    {
        case FXJ_FAIL_NO_SLOT:
            return no_slot_retried ? PP_END_FAULT_REFUSED : PP_END_RETRY_AFTER_REMOUNT;
        case FXJ_FAIL_REFUSED:
            return PP_END_FAULT_REFUSED;
        case FXJ_FAIL_FULL:
            return PP_END_FAULT_FULL;
        case FXJ_FAIL_CARD_WRITE:
            return slot_present ? PP_END_FAULT_WRITE : PP_END_FAULT_REMOVED;
        case FXJ_FAIL_CARD_READ:
            return slot_present ? PP_END_FAULT_READ : PP_END_FAULT_REMOVED;
        default:
            return PP_END_ORIGINAL_AT_POS;           /* NO_ENGINE, SOURCE, BAD_REQUEST */
    }
}

uint32_t pp_played_samples(uint32_t bytes_read, uint32_t avail, uint32_t pos, uint32_t queued_blocks)
{
    const uint32_t unread_bytes = (avail > pos) ? (avail - pos) : 0U;
    if (bytes_read <= unread_bytes)
    {
        return 0U;
    }
    const uint32_t handed_out = (bytes_read - unread_bytes) / PP_BYTES_PER_SAMPLE;  /* gone into blocks */
    const uint32_t queued = queued_blocks * PP_BLOCK_SAMPLES;                       /* not heard yet */
    return (handed_out > queued) ? (handed_out - queued) : 0U;
}

uint32_t pp_pos_blocks(uint32_t played_samples, uint32_t spb)
{
    return (spb == 0U) ? 0U : (played_samples / spb);
}

uint32_t pp_original_offset(uint32_t pos_blocks, uint32_t data_size)
{
    const uint64_t offset = (uint64_t)pos_blocks * PP_SPB_SOURCE * PP_BYTES_PER_SAMPLE;
    return (offset >= data_size) ? 0U : (uint32_t)offset;
}

uint32_t pp_fx_offset(uint32_t pos_blocks, uint32_t spb, uint32_t data_size)
{
    const uint64_t offset = (uint64_t)pos_blocks * spb * PP_BYTES_PER_SAMPLE;
    return (offset >= data_size) ? 0U : (uint32_t)offset;
}
